            padding-bottom: 4px;
        }

        .body-text {
            text-align: justify;
            margin: 12px 0;
        }

        .indent {
            margin-left: 0.5in;
            text-indent: -0.5in;
        }

        .two-col {
            display: flex;
            gap: 0.5in;
            margin-bottom: 20px;
        }

        .col {
            flex: 1;
        }

        .placeholder {
            border: 1px solid #999;
            background: #f5f5f5;
            padding: 10px;
            margin: 15px 0;
            text-align: center;
            font-style: italic;
            color: #555;
        }

        .signature {
            text-align: right;
            margin-top: 40px;
            font-family: 'Georgia', serif;
        }

        table {
            width: 100%;
            border-collapse: collapse;
            margin: 20px 0;
        }

