        <div class="section">
            <div class="heading">Key Statistics</div>
            <table>
                <tr>
                    <th>Metric</th>
                    <th>2024</th>
                    <th>2025</th>
                    <th>Change</th>
                </tr>
                <tr>
                    <td>GDP Growth</td>
                    <td>2.8%</td>
                    <td>3.2%</td>
                    <td>+0.4%</td>
                </tr>
                <tr>
                    <td>Job Creation</td>
                    <td>1.2 million</td>
                    <td>1.8 million</td>
                    <td>+0.6 million</td>
                </tr>
                <tr>
                    <td>Border Crossings</td>
                    <td>4.2 million</td>
                    <td>1.1 million</td>
                    <td>-3.1 million</td>
                </tr>
            </table>
        </div>

        <!-- Placeholder for Photo -->
        <div class="section">
            <div class="heading">Photo: Inauguration Ceremony</div>
            <div class="placeholder" style="width: 100%; height: 200px; text-align: center; display: flex; align-items: center; justify-content: center; font-size: 11pt;">
