        <div class="section">
            <div class="heading">Foreign Policy Priorities</div>
            <ul style="margin: 0; padding-left: 20px;">
                <li>Strengthening alliances in Europe and the Indo-Pacific</li>
                <li>Negotiating fair trade agreements with China and Mexico</li>
                <li>Expanding our defense capabilities</li>
            </ul>
        </div>

        <!-- Signature -->
        <div class="signature">
            <div style="border-top: 1px solid #000; width: 180px; margin: 0 auto 8px;"></div>
            <div style="font-family: 'Georgia', serif; font-size: 12pt;">Joseph R. Biden</div>
            <div style="font-size: 11pt;">President of the United States</div>
        </div>
    </div>
</body>
</html>
